from ta_messaging.exceptions import MessageTypeDoesNotExistInProtocol, ProtocolNotSupported
from ta_messaging.submodule_ute_common_abstract_core.aliases_registry import aliases_registry
from ute_common_abstract_core.exceptions import UnknownAlias
from ta_messaging.message_types_utils import message_exists_in_protocol, all_messages_in_protocol
import re


def drop_message(message, occurrence="any"):
    """
    :param message: string which define expected messages, e.g. UE_1:RRC_RRCConnectionReconfiguration
    :param occurrence: number of the message to be dropped in order of appearing. It can also be a range e.g. 5:7
        means drop messages 5, 6 and 7. Default value "any" means drop all messages
    :return: None
    """
    occurrence = _get_verified_occurrence(occurrence)
    device, msg_description = _get_device_and_msg_description(message)
    _get_device_method(device, 'drop_msg', 'drop_message')(msg_description, occurrence)


def delay_message(message, delay, occurrence="any"):
    """
    :param message: string which define expected messages, e.g. UE_1:RRC_RRCConnectionReconfiguration
    :param delay: time in milliseconds, in string format, e.g. '10ms'
    :param occurrence: number of the message to be delayed in order of appearing. It can also be a range e.g. 5:7
        means delay messages 5, 6 and 7. Default value "any" means delay all messages
    :return: None
    """
    regex = r'\d+ms'
    if not re.match(regex, delay):
        raise ValueError("Delay should be provided in milliseconds, in string format, e.g. '10ms'")
    occurrence = _get_verified_occurrence(occurrence)
    device, msg_description = _get_device_and_msg_description(message)
    _get_device_method(device, 'delay_msg', 'delay_message')(msg_description, delay, occurrence)


def _get_device_and_msg_description(message):
    regex = r'(?P<device_name>\S+):(?P<msg_description>(?P<msg_protocol>\S+)_(?P<msg_type>\S+))'
    match = re.match(regex, message)
    if match:
        device_name = match.group('device_name')
        msg_description = match.group('msg_description')
        msg_protocol = match.group('msg_protocol')
        msg_type = match.group('msg_type')

        _verify_message_protocol(msg_protocol)
        _verify_message_type(msg_protocol, msg_type)

        device = _get_device(device_name)
        return device, msg_description
    raise ValueError("Message description should be provided in following format: "
                     "<alias_name>:<protocol>_<message_type>, e.g. "
                     "UE_1:RRC_RRCConnectionReconfiguration")


def _verify_message_protocol(msg_protocol):
    if msg_protocol not in ['RRC', 'S1AP', 'X2AP']:
        raise ProtocolNotSupported("Wrong message protocol: {}, supported protocols: RRC, S1AP, X2AP".format(msg_protocol))


def _verify_message_type(msg_protocol, msg_type):
    if not message_exists_in_protocol(msg_type, msg_protocol):
        raise MessageTypeDoesNotExistInProtocol('Message {} does not exists inside protocol {}, possible values {}'.
                                                format(msg_type, msg_protocol, all_messages_in_protocol(msg_protocol)))


def _get_verified_occurrence(occurrence):
    search = re.search(r'^(\d+):(\d+)$', occurrence)
    if occurrence.isdigit():
        return int(occurrence)
    elif search:
        lower = int(search.group(1))
        upper = int(search.group(2))
        return lower, upper
    elif occurrence == 'any':
        return 'any'
    else:
        raise ValueError('Invalid parameter occurrence. It should be either a number, a range e.g. 5:7 or "any"')


def _get_device(alias):
    if alias not in aliases_registry():
        if '{}__identification'.format(alias) not in aliases_registry():
            raise UnknownAlias(alias)
        else:
            raise EnvironmentError('Please call ute_ue.require_ue instead of ta_messaging.create_cell_alias for alias: {}'.format(alias))
    return aliases_registry()[alias]


def _get_device_method(device, required_method, calling_method_name):
    try:
        return getattr(device, required_method)
    except AttributeError:
        raise NotImplementedError('{} does not support {}'.format(device.__class__.__name__, calling_method_name))
